#include <string>
#include <vector>
#include <algorithm>

class Solution {
private:
    long long countUpto(long long N, int limit, const std::string& s) {
        std::string strN = std::to_string(N);
        if (strN.size() < s.size()) return 0;
        for (char c : s) {
            if (c - '0' > limit) return 0;
        }
        int pLen = strN.size() - s.size();
        std::string suffix = strN.substr(pLen);
        std::vector<std::vector<long long>> memo(pLen + 1, std::vector<long long>(2, -1));

        auto dp = [&](auto& self, int i, bool isLess, bool isTight) -> long long {
            if (i == pLen) {
                if (isLess) return 1;
                return s <= suffix ? 1 : 0;
            }
            if (!isTight && memo[i][isLess] != -1) return memo[i][isLess];
            int up = isTight ? (strN[i] - '0') : 9;
            long long ans = 0;
            for (int d = 0; d <= std::min(up, limit); ++d) {
                ans += self(self, i + 1, isLess || (d < (strN[i] - '0')), isTight && (d == up));
            }
            if (!isTight) memo[i][isLess] = ans;
            return ans;
        };
        return dp(dp, 0, false, true);
    }
public:
    long long numberOfPowerfulInt(long long start, long long finish, int limit, std::string s) {
        return countUpto(finish, limit, s) - countUpto(start - 1, limit, s);
    }
};

import java.util.Arrays;

class Solution {
    private long countUpto(long N, int limit, String s) {
        String strN = Long.toString(N);
        if (strN.length() < s.length()) return 0;
        for (char c : s.toCharArray()) {
            if (c - '0' > limit) return 0;
        }
        int pLen = strN.length() - s.length();
        String suffix = strN.substring(pLen);
        long[][] memo = new long[pLen + 1][2];
        for (long[] row : memo) Arrays.fill(row, -1);

        return dp(0, false, true, pLen, strN, suffix, s, limit, memo);
    }

    private long dp(int i, boolean isLess, boolean isTight, int pLen, String strN, String suffix, String s, int limit, long[][] memo) {
        if (i == pLen) {
            if (isLess) return 1;
            return s.compareTo(suffix) <= 0 ? 1 : 0;
        }
        if (!isTight && memo[i][isLess ? 1 : 0] != -1) return memo[i][isLess ? 1 : 0];
        int up = isTight ? (strN.charAt(i) - '0') : 9;
        long ans = 0;
        for (int d = 0; d <= Math.min(up, limit); d++) {
            ans += dp(i + 1, isLess || (d < (strN.charAt(i) - '0')), isTight && (d == up), pLen, strN, suffix, s, limit, memo);
        }
        if (!isTight) memo[i][isLess ? 1 : 0] = ans;
        return ans;
    }

    public long numberOfPowerfulInt(long start, long finish, int limit, String s) {
        return countUpto(finish, limit, s) - countUpto(start - 1, limit, s);
    }
}

var numberOfPowerfulInt = function(start, finish, limit, s) {
    function countUpto(N) {
        const strN = String(N);
        if (strN.length < s.length) return 0n;
        for (const c of s) {
            if (Number(c) > limit) return 0n;
        }
        const pLen = strN.length - s.length;
        const suffix = strN.slice(pLen);
        const memo = new Map();

        function dp(i, isLess, isTight) {
            if (i === pLen) {
                if (isLess) return 1n;
                return s <= suffix ? 1n : 0n;
            }
            const key = `${i}_${isLess ? 1 : 0}`;
            if (!isTight && memo.has(key)) return memo.get(key);
            const up = isTight ? Number(strN[i]) : 9;
            let ans = 0n;
            for (let d = 0; d <= Math.min(up, limit); d++) {
                ans += dp(i + 1, isLess || d < Number(strN[i]), isTight && d === up);
            }
            if (!isTight) memo.set(key, ans);
            return ans;
        }
        return dp(0, false, true);
    }
    return Number(countUpto(finish) - countUpto(start - 1));
};
